<template><div class="page"><h2>用户与权限</h2><p>管理员可以为每个普通用户单独分配平台功能权限。</p><el-card><b>当前会话</b><span v-if="profile">{{profile.username}} · {{roleLabel(profile.role)}}</span><el-alert v-else title="未登录或会话已过期" type="warning" :closable="false"/></el-card><el-card v-if="isAdmin"><template #header><b>创建用户账号</b></template><el-form inline><el-form-item label="用户名称"><el-input v-model="form.username"/></el-form-item><el-form-item label="登录密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="初始权限"><el-select v-model="form.permissions" multiple collapse-tags><el-option v-for="p in catalog" :key="p.key" :value="p.key" :label="p.label"/></el-select></el-form-item><el-button type="primary" @click="createUser">创建用户</el-button></el-form></el-card><el-card v-if="isAdmin"><template #header><b>用户权限管理</b></template><el-table :data="users" stripe><el-table-column prop="username" label="用户" width="180"/><el-table-column label="角色" width="110"><template #default="s"><el-tag :type="s.row.role==='admin'?'danger':'info'">{{roleLabel(s.row.role)}}</el-tag></template></el-table-column><el-table-column label="已授权功能"><template #default="s"><el-checkbox-group v-if="s.row.role!=='admin'" v-model="s.row.permissions"><el-checkbox v-for="p in catalog" :key="p.key" :value="p.key" :label="p.key" :disabled="p.key==='view'">{{p.label}}</el-checkbox></el-checkbox-group><span v-else>管理员拥有全部权限</span></template></el-table-column><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="s.row.role!=='admin'" type="primary" link @click="savePermissions(s.row)">保存</el-button></template></el-table-column></el-table></el-card><el-card><template #header><b>角色权限目录</b></template><el-table :data="roles"><el-table-column prop="key" label="角色" width="180"><template #default="s">{{roleLabel(s.row.key)}}</template></el-table-column><el-table-column label="权限"><template #default="s"><el-tag v-for="x in s.row.permission_labels" :key="x">{{x}}</el-tag></template></el-table-column></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const profile=ref(null),roles=ref([]),users=ref([]),catalog=ref([]),form=ref({username:'',password:'',permissions:['view']}),roleLabel=r=>r==='admin'?'管理员':'普通用户',isAdmin=computed(()=>profile.value?.role==='admin');async function load(){try{profile.value=(await api.get('/permissions/profile/')).data;const data=(await api.get('/permissions/roles/')).data;roles.value=data.roles||[];users.value=data.users||[];catalog.value=data.permission_catalog||[]}catch{profile.value=null}}async function createUser(){try{await api.post('/permissions/assign-role/',{username:form.value.username,password:form.value.password,role:'viewer',permissions:form.value.permissions});ElMessage.success('用户账号创建成功');form.value={username:'',password:'',permissions:['view']};await load()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}}async function savePermissions(user){try{const r=await api.post('/permissions/assign-role/',{user_id:user.id,role:'viewer',permissions:user.permissions});user.permissions=r.data.permissions;ElMessage.success(`已保存 ${user.username} 的权限`)}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}}onMounted(load)</script>
<style scoped>.page{padding:24px;max-width:1300px}.page h2{margin-bottom:8px}.page>p{color:#8391a5}.el-card{margin-bottom:16px}.el-card span{margin-left:18px}.el-tag{margin:3px}.el-select{min-width:280px}.el-checkbox{margin:4px 18px 4px 0}</style>
